-- =====================================================================
-- Rewrite receipt_path prefixes to the new user's storage folder.
-- NOTE: this only updates the DB paths. The actual objects still have to be
-- copied into the new project's `receipts` bucket under the new prefix.
-- =====================================================================
UPDATE public.transactions
SET receipt_path = '6ece8c70-8ea7-4676-a021-86c2d24f8a37/' ||
                   substring(receipt_path from length('7b9214b0-364e-4af4-b28c-7d3485fc7e4a/') + 1)
WHERE user_id = '6ece8c70-8ea7-4676-a021-86c2d24f8a37'
  AND receipt_path LIKE '7b9214b0-364e-4af4-b28c-7d3485fc7e4a/%';

COMMIT;

-- =====================================================================
-- VERIFY (run after COMMIT)
-- =====================================================================
SELECT
  (SELECT count(*) FROM public.accounts     WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37') AS accounts,     -- expect 2
  (SELECT count(*) FROM public.categories   WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37') AS categories,   -- expect 30
  (SELECT count(*) FROM public.projects     WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37') AS projects,     -- expect 3
  (SELECT count(*) FROM public.transactions WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37') AS transactions, -- expect 112
  (SELECT coalesce(sum(amount),0) FROM public.transactions WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37' AND type='expense') AS total_expense, -- expect 212370.00
  (SELECT coalesce(sum(amount),0) FROM public.transactions WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37' AND type='income')  AS total_income;  -- expect 1255000.00

-- orphaned foreign keys (expect 0,0,0)
SELECT
  count(*) FILTER (WHERE category_id IS NOT NULL AND category_id NOT IN (SELECT id FROM public.categories)) AS bad_category,
  count(*) FILTER (WHERE account_id  IS NOT NULL AND account_id  NOT IN (SELECT id FROM public.accounts))   AS bad_account,
  count(*) FILTER (WHERE project_id  IS NOT NULL AND project_id  NOT IN (SELECT id FROM public.projects))   AS bad_project
FROM public.transactions WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37';

-- receipt paths (expect 2, and 0 rows still on the old prefix)
SELECT
  count(receipt_path) AS receipts_with_path,
  count(*) FILTER (WHERE receipt_path LIKE '7b9214b0-364e-4af4-b28c-7d3485fc7e4a/%') AS still_old_prefix,
  count(*) FILTER (WHERE receipt_path LIKE '6ece8c70-8ea7-4676-a021-86c2d24f8a37/%') AS on_new_prefix
FROM public.transactions WHERE user_id='6ece8c70-8ea7-4676-a021-86c2d24f8a37';
